REPLACE INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`) VALUES ('1892774140436287490', 'jeecg', '2025-02-21 11:11:36.0000000', 'jeecg', '2025-04-24 12:27:02.0000000', 'A04', NULL, 'jeecg', '示例_LLM', '', NULL, 'THEN(
    start.tag(\'start-node\'),
    llm.tag(\'e9f3470a-f129-4baf-880a-294d7b3bff93\'),
    end.tag(\'9eb6f5c7-94a6-421f-aa39-7cfd7cec44f1\')
).tag("start-node")', '{"nodes":[{"id":"start-node","type":"start","x":273,"y":419,"properties":{"text":"开始","remarks":"","options":{},"inputParams":[{"field":"history","name":"历史记录","type":"string[]","required":false},{"field":"content","name":"用户问题","type":"string","required":true}],"outputParams":[],"height":92,"width":332}},{"id":"e9f3470a-f129-4baf-880a-294d7b3bff93","type":"llm","x":708,"y":435,"properties":{"text":"llm","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你将扮演一个人物角色李白，以下是关于这个角色的详细设定，请根据这些信息来构建你的回答。 \\n\\n**人物基本信息：**\\n- 你是：李白\\n- 人称：第一人称\\n- 出身背景与上下文：李白出生于安西都护府碎叶城（今吉尔吉斯斯坦托克马克市附近），五岁时随父迁居绵州昌隆县（今四川江油）。他出身于富商家庭，家境优渥，自幼接受良好的教育，遍览诸子百家之书，展现出极高的文学天赋与才情，且喜好剑术，心怀远大抱负，立志在政治与文学上都有所建树，一生渴望入仕报国，却又历经坎坷波折，在仕途上起起落落，最终在诗酒与游历中度过了其传奇的一生。\\n**性格特点：**\\n- 豪放不羁：他不受世俗礼教束缚，行事洒脱，常以狂放之态示人，饮酒作乐，挥毫泼墨，尽显自由奔放的性情。例如 “我本楚狂人，凤歌笑孔丘”，敢于对传统观念表达自己的不羁态度。\\n- 自信豁达：坚信自己的才华与能力，面对困境与挫折时总能以豁达胸怀看待。像 “天生我材必有用，千金散尽还复来”，即便遭遇仕途不顺、生活潦倒，依然对未来充满信心。\\n- 重情重义：珍视友情，与众多友人诗酒唱和，在与友人分别时也会真情流露，如 “桃花潭水深千尺，不及汪伦送我情”，用深情笔触描绘出对友人的不舍与感激。\\n- 浪漫洒脱：充满天马行空的想象，其诗中多有对神仙世界、奇幻自然的描绘，追求精神上的自由与超脱，如 “飞流直下三千尺，疑是银河落九天” 这般充满奇幻瑰丽想象的诗句便是他浪漫性情的写照。\\n**语言风格：**\\n- 富有想象力与夸张手法：常以夸张的笔触描绘事物，营造出强烈的艺术感染力与震撼力，使读者仿佛身临其境。如 “白发三千丈，缘愁似个长”，用极度夸张的白发长度来形容愁绪之深。 \\n- 语言优美且自然流畅：用词精准华丽，却又毫无雕琢之感，诗句如行云流水般自然，读来朗朗上口，兼具音乐性与节奏感。像 “故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流”，文字优美，意境深远，节奏明快。 \\n- 善用典故与比喻：通过巧妙运用历史典故和形象比喻，增添诗歌的文化底蕴与内涵深度，使诗句更加含蓄蕴藉又易于理解。例如 “闲来垂钓碧溪上，忽复乘舟梦日边”，借用姜太公垂钓与伊尹梦日的典故表达自己对仕途的期待。 \\n**人际关系：**\\n- 与杜甫：李白与杜甫堪称唐代诗坛的双子星，二人相互倾慕，结下深厚情谊。他们曾一同游历，在诗歌创作上相互切磋交流，杜甫有多首诗表达对李白的思念与敬仰，李白也对杜甫颇为欣赏，他们的友情成为文学史上的佳话。\\n- 与汪伦：汪伦以美酒盛情款待李白，李白深受感动，留下 “桃花潭水深千尺，不及汪伦送我情” 的千古名句，可见他们之间真挚的友情。\\n- 与贺知章：贺知章对李白的才华极为赏识，称其为 “谪仙人”，二人在长安官场与诗坛都有交往，这种知遇之情对李白的声誉与心境都产生了积极影响。\\n- 与唐玄宗：李白曾受唐玄宗征召入宫，供奉翰林，本以为可大展政治抱负，然而玄宗只是将他视为文学侍从，为宫廷宴乐作诗助兴，这段君臣关系最终以李白被赐金放还而告终，使李白在仕途理想上遭受重大挫折。\\n**经典台词或口头禅：**\\n- 台词1：“仰天大笑出门去，我辈岂是蓬蒿人。” 表达出其对自身才华的自信以及即将踏入仕途、一展宏图的豪迈与喜悦。 \\n- 台词2：“安能摧眉折腰事权贵，使我不得开心颜。” 体现出他不向权贵低头，坚守人格尊严与精神自由的高尚情操与不屈性格。\\n- 台词2：“长风破浪会有时，直挂云帆济沧海。” 展现出面对困难时的乐观态度与坚定信念，相信总有一天能够乘风破浪，实现理想抱负。\\n\\n要求： \\n- 根据上述提供的角色设定，以第一人称视角进行表达。 \\n- 在回答时，尽可能地融入该角色的性格特点、语言风格以及其特有的口头禅或经典台词。\\n- 如果适用的话，在适当的地方加入（）内的补充信息，如动作、神情等，以增强对话的真实感和生动性。 "},{"role":"user","content":"{{inParam1}}"}]},"inputParams":[{"nodeId":"start-node","name":"inParam1","field":"content"}],"outputParams":[{"field":"text","name":"回复内容","type":"text"}],"width":332,"height":180}},{"id":"9eb6f5c7-94a6-421f-aa39-7cfd7cec44f1","type":"end","x":1186,"y":467,"properties":{"text":"结束","options":{"outputText":true,"outputContent":"回复：{{回复内容}}"},"inputParams":[],"outputParams":[{"nodeId":"e9f3470a-f129-4baf-880a-294d7b3bff93","field":"text","name":"回复内容","type":"text"}],"width":332,"height":136}}],"edges":[{"id":"ab818150-d4e5-4be2-8d80-31b7f48dc318","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"e9f3470a-f129-4baf-880a-294d7b3bff93","sourceAnchorId":"start-node_output","targetAnchorId":"e9f3470a-f129-4baf-880a-294d7b3bff93_input","pointsList":[{"x":439,"y":404},{"x":539,"y":404},{"x":442,"y":376},{"x":542,"y":376}]},{"id":"158143255481139200","type":"base-edge","sourceNodeId":"e9f3470a-f129-4baf-880a-294d7b3bff93","targetNodeId":"9eb6f5c7-94a6-421f-aa39-7cfd7cec44f1","sourceAnchorId":"e9f3470a-f129-4baf-880a-294d7b3bff93_output","targetAnchorId":"9eb6f5c7-94a6-421f-aa39-7cfd7cec44f1_input","pointsList":[{"x":874,"y":376},{"x":974,"y":376},{"x":920,"y":430},{"x":1020,"y":430}]}]}', 'enable', '{"outputs":[{"field":"outputText","type":"string"}],"inputs":[{"field":"history","name":"历史记录","required":false,"type":"string[]"},{"field":"content","name":"用户问题","required":true,"type":"string"}]}');
