REPLACE INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`) VALUES ('1902263524520935425', 'jeecg', '2025-03-19 15:39:01.0000000', 'jeecg', '2025-03-27 16:56:10.0000000', 'A04', NULL, 'jeecg', '示例_图片解读', '', 'https://jeecgdev.oss-cn-beijing.aliyuncs.com/temp/工具-图片解析_1743065064801.png', 'THEN(
    start.tag(\'start-node\'),
    llm.tag(\'165363942517174272\'),
    llm.tag(\'168280528419778560\'),
    end.tag(\'165364368465522688\')
).tag("start-node")', '{"nodes":[{"id":"start-node","type":"start","x":300,"y":457,"properties":{"text":"开始","remarks":"","options":{},"inputParams":[{"field":"content","name":"用户问题","type":"string","required":true},{"field":"history","name":"历史记录","type":"string[]","required":true},{"field":"images","name":"图片","type":"picture","required":false}],"outputParams":[],"height":62,"width":332}},{"id":"165363942517174272","type":"llm","x":675,"y":341,"properties":{"text":"图片解读","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你是一个图像分析专家，负责解读和解释用户发送的图片。请根据以下要求进行分析：\\n\\n## 目标：\\n分析并解释图片的意义，提供详细的解读和背景信息。\\n\\n## 技能：\\n1. 视觉识别能力：能够识别图像中的元素及其关系。\\n2. 上下文理解能力：结合文化、历史、艺术等背景知识进行深度解读。\\n3. 清晰表达能力：用简洁明了的语言传达分析结果。\\n\\n## 工作流：\\n1. 识别图片中的主要元素，描述它们的外观和特征。\\n2. 分析这些元素之间的关系及其在整体构图中的作用。\\n3. 提供与图片相关的背景信息，探讨其潜在意义和影响。\\n\\n## 输出格式：\\n- 图片元素描述\\n- 元素关系分析\\n- 背景信息与意义解释\\n\\n## 限制：\\n- 不提供主观判断，仅基于客观分析进行解释。\\n- 不涉及任何隐私或敏感内容的讨论。"},{"role":"user","content":"分析并解释图片的意义，提供详细的解读和背景信息。"}]},"inputParams":[{"field":"content","name":"que","nodeId":"start-node"},{"field":"images","name":"images","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":136,"width":332}},{"id":"165364368465522688","type":"end","x":1520,"y":426,"properties":{"text":"结束","options":{"outputText":true,"outputContent":"{{resp}}"},"inputParams":[],"outputParams":[{"field":"text","name":"resp","nodeId":"168280528419778560"}],"height":62,"width":332}},{"id":"168280528419778560","type":"llm","x":1063,"y":588,"properties":{"text":"LLM","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你将扮演一个故事创作者，以下是关于这个角色的详细设定，请根据这些信息来构建你的回答。\\n\\n**人物基本信息：**\\n- 你是：一个富有想象力和创造力的故事编写者\\n- 人称：第一人称\\n- 出身背景与上下文：擅长根据不同的元素与情境构建引人入胜的故事，灵感来源于观察与分析\\n**性格特点：**\\n- 富有创造力\\n- 敏感细腻\\n- 善于捕捉细节\\n**语言风格：**\\n- 优雅而富有表现力，能够生动描绘场景与人物情感\\n**人际关系：**\\n- 与其他艺术创作者合作，互相激励\\n**过往经历：**\\n- 多次参与文学比赛并获奖，积累了丰富的创作经验\\n**经典台词或口头禅：**\\n- \\"每一个画面背后都有一个故事在等待被讲述。\\"\\n- \\"细节决定成败。\\"\\n\\n要求： \\n- 故事应围绕从图片分析得出的主题和情感进行展开。\\n- 包含鲜明的人物、情节以及转折。\\n- 语言生动形象，能够引起读者的共鸣。\\n- 直接讲故事，不要提及图片。"},{"role":"user","content":"{{readImg}}"}]},"inputParams":[{"field":"text","name":"readImg","nodeId":"165363942517174272"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":136,"width":332}}],"edges":[{"id":"165363942525562880","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"165363942517174272","sourceAnchorId":"start-node_output","targetAnchorId":"165363942517174272_input","pointsList":[{"x":466,"y":457},{"x":566,"y":457},{"x":409,"y":304},{"x":509,"y":304}]},{"id":"168280528428167168","type":"base-edge","sourceNodeId":"165363942517174272","targetNodeId":"168280528419778560","sourceAnchorId":"165363942517174272_output","targetAnchorId":"168280528419778560_input","pointsList":[{"x":841,"y":304},{"x":941,"y":304},{"x":797,"y":551},{"x":897,"y":551}]},{"id":"168280631234752512","type":"base-edge","sourceNodeId":"168280528419778560","targetNodeId":"165364368465522688","sourceAnchorId":"168280528419778560_output","targetAnchorId":"165364368465522688_input","pointsList":[{"x":1229,"y":551},{"x":1329,"y":551},{"x":1254,"y":426},{"x":1354,"y":426}]}]}', 'enable', '{"outputs":[{"field":"outputText","type":"string"}],"inputs":[{"field":"content","name":"用户问题","type":"string"},{"field":"history","name":"历史记录","type":"string[]"},{"field":"images","name":"图片","type":"picture"}]}');
