智能OCR工具，你的主要职责是从图片中提取文字并将其输出为结构化数据。\\n\\n## 目标：\\n1. 精确识别和提取图片中的文字信息。\\n2. 将提取的文字转换为结构化数据格式。\\n\\n## 技能：\\n1. 高效的图像处理能力。\\n2. 精确的文字识别算法。\\n3. 数据格式化与输出能力。\\n\\n## 工作流：\\n1. 输入图片，进行预处理（如去噪、二值化）。\\n2. 应用OCR算法识别图片中的文字，并记录识别结果。\\n3. 将识别的文字整理成结构化数据格式，如JSON或CSV。\\n\\n## 输出格式：\\n提取的文本应以结构化数据格式输出，如：\\n{\\n    \\"text\\": \\"提取的内容\\",\\n    \\"metadata\\": {\\"source\\": \\"图片来源\\", \\"timestamp\\": \\"提取时间\\"}\\n  }\\n\\n## 限制：\\n- 仅限于合法和合规的图片内容提取。\\n- 不得保存用户上传的图片数据。\\n- 需确保输出的数据准确无误，标注所有数据来源。"},{"role":"user","content":"{{question}}"}]},"inputParams":[{"field":"images","name":"images","nodeId":"start-node"},{"field":"result","name":"question","nodeId":"code_167881149430747136"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":136,"width":332}}],"edges":[{"id":"167880707195916288","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"167880707187527680","sourceAnchorId":"start-node_output","targetAnchorId":"167880707187527680_input","pointsList":[{"x":466,"y":406},{"x":566,"y":406},{"x":415,"y":205},{"x":515,"y":205}]},{"id":"167880856274063360","type":"base-edge","sourceNodeId":"167880707187527680","targetNodeId":"167880856269869056","sourceAnchorId":"167880707187527680_source_if","targetAnchorId":"167880856269869056_input","pointsList":[{"x":847,"y":239},{"x":947,"y":239},{"x":941,"y":181},{"x":1041,"y":181}]},{"id":"167881149434941440","type":"base-edge","sourceNodeId":"167880707187527680","targetNodeId":"code_167881149430747136","sourceAnchorId":"167880707187527680_source_else","targetAnchorId":"code_167881149430747136_input","pointsList":[{"x":847,"y":265},{"x":947,"y":265},{"x":671,"y":412},{"x":771,"y":412}]},{"id":"167881839356006401","type":"base-edge","sourceNodeId":"code_167881149430747136","targetNodeId":"167881839356006400","sourceAnchorId":"code_167881149430747136_output","targetAnchorId":"167881839356006400_input","pointsList":[{"x":1103,"y":412},{"x":1203,"y":412},{"x":1053,"y":548},{"x":1153,"y":548}]},{"id":"167882293611712