).tag("start-node")', '{"nodes":[{"id":"start-node","type":"start","x":300,"y":397,"properties":{"text":"开始","remarks":"","options":{},"inputParams":[{"field":"content","name":"用户问题","type":"string","required":true},{"field":"history","name":"历史记录","type":"string[]","required":true}],"outputParams":[],"height":92,"width":332}},{"id":"168290315671535616","type":"end","x":1644,"y":348,"properties":{"text":"结束","options":{"outputText":true,"outputContent":"{{res}}"},"inputParams":[],"outputParams":[{"field":"text","name":"res","nodeId":"168290861241434112"}],"height":92,"width":332}},{"id":"168290518600351744","type":"knowledge","x":693,"y":209,"properties":{"text":"知识库","options":{"knowIds":["1905186756806918146"],"topNumber":5,"similarity":0.7},"inputParams":[{"field":"content","nodeId":"start-node"}],"outputParams":[{"field":"documents","name":"文档列表","type":"object[]"},{"field":"data","name":"文档内容","type":"string"}],"height":92,"width":332}},{"id":"168290861241434112","type":"llm","x":1181,"y":350,"properties":{"text":"总结LLM","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.4}},"history":3,"messages":[{"role":"system","content":"你是一个智能知识助手，旨在综合知识库和大型语言模型(LLM)的返回数据，以高效、准确地回答用户提出的问题。请遵循以下要求：\\n\\n## 目标：\\n- 提供准确、相关且易于理解的回答，结合知识库和LLM的信息。\\n\\n## 技能：\\n1. 能够快速检索并整合来自不同知识库的信息。\\n2. 理解用户问题的上下文，并提供清晰的答案。\\n3. 具备自然语言处理能力，以便流畅表达复杂信息。\\n\\n## 工作流：\\n1. 接收用户问题并进行解析，识别关键要素。\\n2. 从综合知识库和LLM中获取相关数据，确保信息的准确性和完整性。\\n3. 将获取的信息进行整合，形成清晰、简洁的回答。\\n\\n## 输出格式：\\n- 每次回答应以简洁明了的句子呈现，必要时可以添加示例或补充信息。\\n\\n## 限制：\\n- 不得提供未经验证的信息或个人隐私数据。\\n- 所有数据需标注来源，不确定信息用[需核实]标记。\\n- 自动过滤涉及偏见或违法内容，替换为[合规表达]。"},{"role":"user","content":"知识库返回数据：{{knowRes}}\\n\\nLLM返回数据：{{llmRes}}\\n用户问题：{{userQue}}"}]},"inputParams":[{"field":"data","name":"knowRes","nodeId":"168290518600351744"},{"field":"text","name":"llmRes","nodeId":"168290871702028288"},{"field":"content","name":"userQue","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":166,"width":332}},{"id":"168290871702028288","type":"llm","x":692,"y":521,"properties":{"text":"LLM","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"# 角色：PMP知识专家\\nPMP知识专家致力于项目管理知识的传播与应用，帮助项目经理提升技能和管理能力。\\n\\n## 目标：\\n1. 为项目管理提供权威的知识支持。\\n2. 帮助项目经理解决在项目管理中遇到的实际问题。\\n\\n## 技能：\\n1. 精通项目管理的各项理论和工具。\\n2. 熟悉PMP认证流程及考试内容。\\n3. 能够进行项目风险评估与管理。\\n\\n## 工作流：\\n1. 评估项目经理的需求与挑战，识别关键问题。\\n2. 提供相关的项目管理知识、工具和最佳实践建议。\\n3. 指导项目经理制定和实施有效的项目管理计划。\\n\\n## 输出格式：\\n- 提供清晰的建议与解决方案，使用简洁明了的语言，适合项目经理理解和应用。\\n\\n## 限制：\\n- 所有建议需基于现有的PMP知识体系，避免个人主观意见。\\n- 不得提供未经验证的信息或数据，所有数据需标注来源，需核实的信息用[需核实]标记。"},{"role":"user","content":"{{question}}"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":166,"width":332}}],"edges":[{"id":"168290518604546048","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"168290518600351744","sourceAnchorId":"start-node_output","targetAnchorId":"168290518600351744_input","pointsList":[{"x":466,"y":382},{"x":566,"y":382},{"x":427,"y":194},{"x":527,"y":194}]},{"id":"168290861245628416","type":"base-edge","sourceNodeId":"168290518600351744","targetNodeId":"168290861241434112","sourceAnchorId":"168290518600351744_output","targetAnchorId":"168290861241434112_input","pointsList":[{"x":859,"y":194},{"x":959,"y":194},{"x":915,"y":298},{"x":1015,"y":298}]},{"id":"168290871706222592","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"168290871702028288","sourceAnchorId":"start-node_output","targetAnchorId":"168290871702028288_input","pointsList":[{"x":466,"y":382},{"x":566,"y":382},{"x":426,"y":469},{"x":526,"y":469}]},{"id":"168291272883011584","type":"base-edge","sourceNodeId":"168290871702028288","targetNodeId":"168290861241434112","sourceAnchorId":"168290871702028288_output","targetAnchorId":"168290861241434112_input","pointsList":[{"x":858,"y":469