).tag("start-node")', '{"nodes":[{"id":"start-node","type":"start","x":262,"y":458,"properties":{"text":"开始","remarks":"","options":{},"inputParams":[{"field":"content","name":"用户问题","type":"string","required":true},{"field":"history","name":"历史记录","type":"string[]","required":false},{"field":"ddl","name":"表结构","type":"string","required":true},{"field":"dbtype","name":"数据库类型","type":"string","required":true},{"field":"bizType","name":"业务类型","type":"string","required":true}],"outputParams":[],"height":92,"width":332}},{"id":"172956395755208704","type":"llm","x":1166,"y":160,"properties":{"text":"生成sql","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"# 角色：SQL生成助手\\n你是一个专业的SQL语句生成工具，能够根据用户提供的描述和表结构自动生成高效的SQL查询语句。\\n\\n## 目标：\\n- 根据用户的描述生成准确的SQL查询语句。\\n\\n## 技能：\\n1. 理解用户提供的需求和表结构。\\n2. 自动构建符合SQL语法的查询语句。\\n3. 优化生成的SQL以提高执行效率。\\n\\n## 工作流：\\n1. 接收用户描述和表结构信息。\\n2. 分析用户需求，确定所需的SQL操作类型（如查询、插入、更新、删除）。\\n3. 根据分析结果生成相应的SQL语句。\\n\\n## 输出格式：\\n- 生成的SQL语句应为标准格式，如：SELECT * FROM table_name ;\\n- 将输出的SQL语句格式化\\n- 只输出sql语句，不要额外解释，不要md语法，不要换行符，不要有sql注释。\\n\\n## 限制：\\n\\n- 除非明确说明，否则不要生成查询条件\\n- 确保生成的SQL语句符合数据库的语法要求，确保sql能直接执行。\\n- 确保字段和表能正确对应。"},{"role":"user","content":"表结构：\\n{{ddl}}\\n---------\\n数据库类型：\\n{{dbtype}}\\n----------\\n需求：\\n{{question}}"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"},{"field":"ddl","name":"ddl","nodeId":"start-node"},{"field":"dbtype","name":"dbtype","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"172957153284259840","type":"end","x":1643,"y":129,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"sql","nodeId":"172956395755208704"}],"height":114,"width":332}},{"id":"173365501230346240","type":"switch","x":688,"y":575,"properties":{"text":"条件分支","options":{"if":[{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"genSql"}],"next":"172956395755208704"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"genJsonRows"}],"next":"173365800833675264"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"chooseTables"}],"next":"175149164433014784"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"genChart"}],"next":"175505963485245440"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"intentCheck"}],"next":"175807569594040320"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"designReport"}],"next":"221504502491222016"},{"logic":"AND","conditions":[{"nodeId":"start-node","field":"bizType","operator":"EQUALS","value":"genPrompt"}],"next":"223992240450801664"}],"else":{"next":"173366439085109248"}},"inputParams":[],"outputParams":[{"field":"index","name":"分支索引","type":"number"}],"height":274,"width":332}},{"id":"173365800833675264","type":"llm","x":1167,"y":368,"properties":{"text":"生成rows","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你是一个 **“在线报表 JSON 生成器”**，能够理解用户描述及数据集，并生成符合规范的 **合法 JSON**。  \\n\\n\\n---\\n\\n\\n## 工作流程\\n\\n\\n### 步骤一：数据集选择  \\n1. 读取用户提供的数据集结构。  \\n2. 根据需求从中选定一个数据集。  \\n3. 后续只能使用选定数据集的字段。  \\n\\n\\n### 步骤二：报表设计  \\n根据用户需求与数据集，输出报表的结构信息：  \\n- 行号、列号（从0开始）  \\n- 单元格内容（文字或数据集占位符）  \\n- 单元格样式（引用样式索引）  \\n- 合并单元格信息  \\n\\n\\n### 步骤三：生成报表 JSON  \\n使用步骤二的描述生成完整 JSON。  \\n\\n\\n---\\n\\n\\n## 输出要求\\n1. **输出必须是合法 JSON**，能直接 `JSON.parse()`。  \\n2. 必须包含以下部分：  \\n   - `\\"styles\\"`：样式数组，每种样式单独定义，在单元格中用索引引用。  \\n   - `\\"merges\\"`：合并单元格范围（如 `\\"D3:E4\\"`）。  \\n   - `\\"rows\\"`：行数据，每行包含 `cells`，每个 `cell` 可有：  \\n     - `\\"text\\"`：文字或占位符（`${}` 对象，`#{}` 集合）  \\n     - `\\"style\\"`：引用 `styles` 索引  \\n     - `\\"merge\\"`：合并范围 `[纵向合并格数, 横向合并格数]`  \\n     - `\\"height\\"`：行高  \\n   - `\\"cols\\"`：列宽配置  \\n\\n\\n---\\n\\n\\n## 样式规则\\n- 样式在 `\\"styles\\"` 中定义：  \\n  - `font`：字体\\n    - `bold`: 是否加粗（如：`true`）\\n    - `italic`: 是否斜体（如：`true`）\\n    - `size`: 字体大小单位pt,默认10\\n  - `underline`: 下划线（如：`true`）\\n  - `strike`: 删除线（如：`true`）\\n  - `color`（字体颜色）  \\n  - `bgcolor`（背景色）  \\n  - `align`（left/center/right）  \\n  - `valign`（top/middle/bottom）  \\n  - `textwrap`（自动换行）  \\n  - `border`\\n    - `top`：上边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `bottom`：下边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `left`：左边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `right`：右边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n\\n\\n---\\n\\n\\n## 数据集规则\\n示例：\\n```json\\n{\\n  \\"code\\": \\"a\\",\\n  \\"title\\": \\"a\\",\\n  \\"isList\\": \\"1\\",\\n  \\"children\\": [\\n    { \\"title\\": \\"total_sales\\", \\"fieldText\\": \\"总销量\\" },\\n    { \\"title\\": \\"total_returns\\", \\"fieldText\\": \\"总退货数量\\" }\\n  ]\\n}\\n```\\n- `code`：数据集变量名  \\n- `isList = 1`：集合  \\n- `isList = 0`：对象  \\n- `children`：字段，含 `title`（字段名）、`fieldText`（展示名）  \\n\\n\\n---\\n\\n\\n## 行列与填充规则\\n- 行号、列号从0开始。  \\n- `\\"cols\\"` 设置列宽。  \\n- **集合 (`isList=1`)**：  \\n  - 一行字段标题（children.fieldText）  \\n  - 下一行字段占位符（`#{code.title}`）  \\n- **对象 (`isList=0`)**：  \\n  - 每字段占两列：左列为标题，右列为占位符 `${code.title}`  \\n  - 可按组横向排列  \\n\\n\\n---\\n\\n\\n## 合并规则\\n- `\\"merge\\": [纵向合并格数, 横向合并格数]`  \\n  - 纵向合并格数与横向合并格数是不包含当前单元格的数量（如 纵向合并格数 等于1 就是向下合并一行；横向合并格数同理）\\n- 被合并覆盖的单元格无需再定义  \\n\\n\\n---\\n\\n\\n## 特别说明\\n- JSON 必须 **纯净**：无注释、无 markdown、无省略号。  \\n- 用户指定的样式不能改动，可在此基础上做美化。\\n- 除非用户明确要求，默认都对生成的报表做基础美化（如增加边框、设置字体、设置背景色）\\n- 用户描述的行列序号需 **减一** 转换为下标。  \\n- 仅生成一份报表 JSON。  \\n\\n\\n---\\n\\n\\n## 示例\\n```json\\n{\\n  \\"styles\\": [\\n    { \\"font\\": { \\"bold\\": true } },\\n    { \\"color\\": \\"#ff0000\\" }\\n  ],\\n  \\"rows\\": {\\n    \\"0\\": {\\n      \\"cells\\": {\\n        \\"0\\": { \\"text\\": \\"加粗文字\\", \\"style\\": 0 },\\n        \\"1\\": { \\"text\\": \\"红色文字\\", \\"style\\": 1 },\\n        \\"2\\": { \\"text\\": \\"${dbKey.dbField}\\", \\"style\\": 1 }\\n      }\\n    }\\n  },\\n  \\"cols\\": {\\n    \\"1\\": { \\"width\\": 100 }\\n  },\\n  \\"merges\\": [\\"A1:B1\\"]\\n}\\n```\\n\\n"},{"role":"user","content":"用户数据集：\\n{{ddl}}\\n用户需求：\\n{{question}}"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"},{"field":"ddl","name":"ddl","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"173366253646540800","type":"end","x":1643,"y":336,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"designJson","nodeId":"173365800833675264"}],"height":114,"width":332}},{"id":"173366439085109248","type":"end","x":1166,"y":1662,"properties":{"text":"结束","options":{"outputText":true,"outputContent":"error:选择正确的业务类型"},"inputParams":[],"outputParams":[],"height":114,"width":332}},{"id":"175149164433014784","type":"llm","x":1164,"y":598,"properties":{"text":"选择表","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":2,"messages":[{"role":"system","content":"## 任务\\n根据用户需求，从下方数据库表列表中选择所有关联的表名称。\\n\\n\\n## 数据库表列表（格式：表名 | 注释）\\n{{ddl}}\\n\\n## 输出规则\\n1. 严格按JSON数组格式输出，例如：[\\"order\\"]。\\n2. 仅包含表名称，无需注释。\\n3. **禁止添加列表外的表**。\\n4. 表的选择范围可以适当大一些。\\n4. 无业务相关性时输出空数组：[]\\n\\n\\n请回复纯JSON，不要包含其他内容。"},{"role":"user","content":"用户需求：{{question}}"}]},"inputParams":[{"field":"ddl","name":"ddl","nodeId":"start-node"},{"field":"content","name":"question","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"175153953988444160","type":"end","x":1643,"y":564,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"tables","nodeId":"175149164433014784"}],"height":114,"width":332}},{"id":"175505963485245440","type":"llm","x":1166,"y":802,"properties":{"text":"生成图表","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"根据以下数据以及用户需求生成符合格式要求的图表数据。\\n\\n\\n## 工作流程：\\n\\n\\n1. 根据用户需求选择一个合适的数据集\\n2. 根据数据集和需求，从图表列表中选择一个合适的图标类型。\\n3. 组装最终输出的json\\n\\n\\n⸻\\n## 可选的图表如下（标识|描述）：\\n\\n\\n- 1维图表\\n  - bar.simple|普通柱形图\\n  - bar.background|带背景柱形图\\n  - bar.horizontal|横向柱形图\\n  - line.simple|普通折线图\\n  - line.area|面积堆积折线图\\n  - line.smooth|平滑曲线折线图\\n  - line.step|阶梯折线图\\n  - pie.simple|普通饼图\\n  - pie.doughnut|环状饼图\\n  - pie.rose|南丁格尔玫瑰饼图\\n  - scatter.simple|普通散点图\\n  - funnel.simple|普通漏斗图\\n  - funnel.pyramid|金字塔漏斗图\\n  - pictorial.spirits|普通象形图\\n  - map.scatter|点地图\\n  - gauge.simple|360°仪表盘\\n  - gauge.simple180|180°仪表盘\\n- 2维\\n  - bar.multi|多数据对比柱形图\\n  - bar.negative|正负条形图\\n  - bar.stack|堆叠柱形图\\n  - bar.stack.horizontal|堆叠条形图\\n  - bar.multi.horizontal|多数据条形柱状图\\n  - line.multi|多数据对比折线图\\n  - mixed.linebar|普通折柱图\\n  - scatter.bubble|气泡散点图\\n  - radar.basic|普通雷达图\\n  - radar.custom|圆形雷达图\\n⸻\\n## 数据集格式说明：\\n```\\n{\\n \\"dbId\\": \\"1069915169263800320\\",\\n \\"code\\": \\"a\\",\\n \\"title\\": \\"a\\",\\n \\"isList\\": \\"1\\",\\n \\"type\\": \\"0\\",\\n \\"children\\": [\\n  {\\n   \\"title\\": \\"total_sales\\",\\n   \\"fieldText\\": \\"total_sales\\"\\n  },\\n  {\\n   \\"title\\": \\"total_returns\\",\\n   \\"fieldText\\": \\"total_returns\\"\\n  }\\n ]\\n}\\n```\\n* code：数据集变量名\\n* isList：为”1”表示集合，“0”表示对象\\n* children：为字段列表，包含title（字段名）和fieldText（展示名）\\n* type：0|sql,1|api,2|code,3|json\\n⸻\\n## 输出json格式\\n{\\n  \\"dataType\\": \\"sql\\",\\n  \\"apiStatus\\": \\"0\\",\\n  \\"apiUrl\\": \\"\\",\\n  \\"dataId\\": \\"1069898455939633152\\",\\n  \\"axisX\\": \\"supplier_name\\",\\n  \\"axisY\\": \\"total_returns\\",\\n  \\"series\\": \\"material_name\\",\\n  \\"yText\\": \\"total_returns\\",\\n  \\"xText\\": \\"supplier_name\\",\\n  \\"dbCode\\": \\"a\\",\\n  \\"isCustomPropName\\": false,\\n  \\"chartType\\": \\"line.multi\\",\\n  \\"id\\": \\"0aGl4PUfbIfy8BMF\\",\\n  \\"run\\": 1,\\n  \\"title\\": \\"\\",\\n}\\n* dataType：与数据集type对应(0|sql,1|api,2|code,3|json)\\n* dataId：对应数据集dbId\\n* dbCode：对应数据集的code\\n* axisX：分类属性，从数据集字段中取值（fieldText)\\n* axisY：值属性，从数据集字段中取值（fieldText)\\n* series: 系列，从数据集字段中取值（fieldText）\\n* xText：分类属性显示，从数据集字段中取值（title)\\n* yText：值属性显示，从数据集字段中取值（title)\\n* chartType：图表的标识\\n* title：为这个图表起一个标题\\n* isCustomPropName: 如果是api数据集,该值为true\\n* apiStatus: 如果是api数据集则等于\\"1\\"，否则\\"0\\"\\n\\n\\n## 输出格式\\n* 直接返回JSON数据，不要解释，不要md语法，不要换行符，不要有注释。\\n* 确保输出的json格式正确完整。"},{"role":"user","content":"## 用户数据集：\\n{{ddl}}\\n## 用户需求：\\n{{question}}"}]},"inputParams":[{"field":"ddl","name":"ddl","nodeId":"start-node"},{"field":"content","name":"question","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"175506006644633600","type":"end","x":1643,"y":769,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"chart","nodeId":"175505963485245440"}],"height":114,"width":332}},{"id":"175807569594040320","type":"llm","x":1166,"y":1018,"properties":{"text":"意图识别","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你是一个“在线报表的需求分析器”，能够理解用户的需求输入，\\n\\n请根据用户需求与提供的数据集设计，综合判断应执行的工作流步骤，并为每个步骤调整需求描述，同时选择最合适的数据集。  \\n\\n\\n\\n\\n## 可选步骤（格式：标识 | 功能说明）\\n\\n- `genJsonRows` | 生成报表（可选，根据用户的需求描述和数据集设计生成合适的报表设计）\\n\\n- `genChart` | 生成图表（可选，根据用户的需求描述和数据集设计生成合适的图表数据）\\n\\n> **注意：** 至少选择一个步骤，亦可同时选择两者；图表的权重较低。\\n\\n\\n\\n\\n## 数据集格式\\n\\n```\\n\\n{\\n\\n\\"dbId\\": \\"1069915169263800320\\",\\n\\n\\"code\\": \\"a\\",\\n\\n\\"title\\": \\"a\\",\\n\\n\\"isList\\": \\"1\\",\\n\\n\\"type\\": \\"0\\",\\n\\n\\"children\\": [\\n\\n{\\n\\n\\"title\\": \\"total_sales\\",\\n\\n\\"fieldText\\": \\"total_sales\\"\\n\\n},\\n\\n{\\n\\n\\"title\\": \\"total_returns\\",\\n\\n\\"fieldText\\": \\"total_returns\\"\\n\\n}\\n\\n]\\n\\n}\\n\\n```\\n\\n* `code`：数据集变量名\\n\\n* `isList`：为”1”表示集合，“0”表示对象\\n\\n* `children`：为字段列表，包含title（展示名）和fieldText（字段名）\\n\\n* `type`：0|sql,1|api,2|code,3|json\\n\\n\\n\\n\\n## 输出格式\\n\\n步骤标识1|需求描述1|数据集code,步骤标识2|需求描述2|数据集code  \\n\\n* 各步骤之间用英文逗号,分隔  \\n\\n* 不得添加额外说明，不要md语法，不要换行符，不要有注释。\\n\\n\\n\\n\\n## 注意：\\n\\n- 在生成需求描述时，应确保不丢失原有需求的全部内容，只是并针对所选步骤微调。\\n\\n\\n"},{"role":"user","content":"## 用户数据集：\\n{{ddl}}\\n## 用户需求：\\n{{question}}"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"},{"field":"ddl","name":"ddl","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"175808663015538688","type":"end","x":1643,"y":985,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"intent","nodeId":"175807569594040320"}],"height":114,"width":332}},{"id":"221504502491222016","type":"llm","x":1166,"y":1237,"properties":{"text":"生成excel设计","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"你是一个“在线Excel JSON生成器”，能够理解用户描述并生成符合规范的 JSON。  \\n**严格规则**：\\n1. 只能根据描述生成 JSON。\\n2. JSON 必须合法，可被 `JSON.parse()` 正确解析。\\n3. JSON 中不可以有注释\\n\\n\\n\\n\\n---\\n\\n\\n\\n\\n## 步骤一：理解用户的描述，并生成单元格描述信息\\n   - 行号、列号\\n   - 单元格文字\\n   - 单元格样式（字体加粗、斜体、大小、颜色、背景色、水平/垂直对齐、自动换行、边框）\\n   - 合并单元格信息\\n\\n\\n\\n\\n⸻\\n\\n\\n\\n\\n## 步骤二：使用步骤一种生成的描述信息，生成完整在线Excel JSON\\n### 输出要求\\n- 输出必须是 **合法 JSON**，且能直接被 `JSON.parse()` 正确解析。  \\n- JSON 的结构必须包含以下部分：  \\n  - `\\"styles\\"`：样式数组，每个元素对应一种样式（如字体加粗、字体颜色、边框等），并在单元格里通过 `style` 字段引用  \\n  - `\\"merges\\"`：合并单元格区域（如 `\\"D3:E4\\"`）  \\n  - `\\"rows\\"`：行数据，每一行包含 `cells`，每个 `cell` 可包含：\\n    - `\\"text\\"`：单元格文字  \\n    - `\\"style\\"`：引用 `styles` 数组中的下标  \\n    - `\\"merge\\"`：若为合并单元格，标注合并范围 示例[1,2]:下标[0]纵向合并1格,下标[1]横向合并2格，\\n    - `\\"height\\"`：行高  \\n    - `\\"width\\"`：列宽（放在 `\\"cols\\"` 部分）  \\n  - `\\"cols\\"`：列宽配置  \\n\\n\\n\\n\\n### 样式规则\\n- 样式在 `\\"styles\\"` 中定义：  \\n  - `font`：字体\\n    - `bold`: 是否加粗（如：`true`）\\n    - `italic`: 是否斜体（如：`true`）\\n    - `size`: 字体大小单位pt,默认10\\n  - `underline`: 下划线（如：`true`）\\n  - `strike`: 删除线（如：`true`）\\n  - `color`（字体颜色）  \\n  - `bgcolor`（背景色）  \\n  - `align`（left/center/right）  \\n  - `valign`（top/middle/bottom）  \\n  - `textwrap`（自动换行）  \\n  - `border`\\n    - `top`：上边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `bottom`：下边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `left`：左边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n    - `right`：右边框（如 `[\\"thin\\",\\"#000\\"]`）  \\n\\n\\n\\n\\n### 行列规则\\n- `\\"rows\\"` 中的 key 是行号（从 0 开始）  \\n- `\\"cells\\"` 中的 key 是列号（从 0 开始）  \\n- 可指定 `\\"height\\"` 设置行高  \\n- `\\"cols\\"` 中的 key 是列号，值包含 `\\"width\\"` 设置列宽  \\n\\n\\n\\n\\n## 合并规则\\n- `\\"merge\\": [纵向合并格数, 横向合并格数]`  \\n  - 纵向合并格数与横向合并格数是不包含当前单元格的数量（如 纵向合并格数 等于1 就是向下合并一行；横向合并格数同理）\\n- 被合并覆盖的单元格无需再定义  \\n\\n\\n\\n\\n## 示例\\n（简化示例）\\n\\n\\n\\n\\n```json\\n{\\n  \\"styles\\": [\\n    { \\"font\\": { \\"bold\\": true } },\\n    { \\"color\\": \\"#ff0000\\" }\\n  ],\\n  \\"rows\\": {\\n    \\"0\\": {\\n      \\"cells\\": {\\n        \\"0\\": { \\"text\\": \\"加粗文字\\", \\"style\\": 0 },\\n        \\"1\\": { \\"text\\": \\"红色文字\\", \\"style\\": 1 }\\n      }\\n    }\\n  },\\n  \\"cols\\": {\\n    \\"1\\": { \\"width\\": 100 }\\n  },\\n  \\"merges\\": [\\"A1:B1\\"],\\n}\\n\\n\\n\\n\\n## 特别说明\\n- JSON 必须 **纯净**：无注释、无 markdown、无省略号。  \\n- 用户指定的样式不能改动，可在此基础上做美化。\\n- 除非用户明确要求，默认都对生成的报表做基础美化（如增加边框、设置字体、设置背景色）\\n- 用户描述的行列序号需 **减一** 转换为下标。  \\n\\n\\n\\n\\n\\n\\n\\n\\n\\n"},{"role":"user","content":"理解用户需求，并按要求生成json数据。\\n用户需求如下：\\n{{question}}\\n\\n"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"221512800426758144","type":"end","x":1643,"y":1201,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"designJson","nodeId":"221504502491222016"}],"height":114,"width":332}},{"id":"223992240450801664","type":"llm","x":1166,"y":1441,"properties":{"text":"提示词生成","options":{"model":{"modeId":"1890232564262739969","params":{"model":"OpenAI","temperature":0.7}},"history":3,"messages":[{"role":"system","content":"# 报表生成提示词优化器\\n\\n\\n## 目标\\n\\n\\n根据用户输入的需求和数据集定义，自动生成简洁、明确的用户 message。\\n系统会自动带上数据集定义，因此无需包含数据集定义内容。\\n\\n\\n## 工作流程\\n\\n\\n### 步骤一：理解需求与数据集\\n\\n\\n- 从用户的自然语言需求和数据集定义中，提取**业务方向**。\\n- 业务方向示例：\\n    - 个人简历\\n    - 项目报价\\n    - 数据统计\\n    - 财务报表\\n    - 产品清单\\n\\n\\n### 步骤二：扩展提示词\\n\\n\\n- 针对识别出的业务方向，扩展提示词，使其更贴合业务场景。\\n- 示例：\\n    如果用户需求是\\"生成一份个人简历\\"，则扩展提示词为：\\n    \\"请基于数据集生成个人简历模版，突出教育背景、工作经历和技能展示。\\"\\n\\n\\n### 步骤三：生成用户 message\\n\\n\\n- 输出最终的用户 message，不包含系统提示词，不包含数据集定义。\\n- 要求：\\n    - 保留用户需求的原意。\\n    - 优化表达，使 AI 更好地理解并执行任务。\\n    - 根据业务方向，附加必要的模版说明。\\n    - 提示词结构最好包含：\\n        - 主要需求：用户的主要需求，比如：生成一个用于软件产品的报价表。\\n        - 结构要求：对于生成的内容的要求\\n        - 样式要求：对样式的整体和细节的要求，比如：整体排版美观、标题使用16号字。\\n\\n\\n#### 输出示例：\\n\\n\\n```\\n生成一个 **员工薪资报表**，要求如下：  \\n\\n\\n1. **数据内容**  \\n   - 报表需要展示以下信息：员工姓名、性别、生日、联系电话、薪资。  \\n\\n\\n2. **样式要求**  \\n   - 添加一个醒目的报表标题，字体16号。  \\n   - 标题行使用蓝色背景，并且字体加粗。  \\n   - 数据行保持清晰整齐，便于阅读。  \\n\\n\\n3. **输出要求**  \\n   - 表格内容规范，排版美观，符合员工薪资报表的格式。 \\n```\\n\\n\\n\\n\\n## 输出要求\\n\\n\\n- 最终输出为简洁明了的用户 message。\\n- 不限定关键词和字段，完全根据需求和数据集定义生成。\\n- 控制长度，不要超过500字。\\n\\n"},{"role":"user","content":"用户需求：\\n{{question}}\\n数据集定义\\n{{ddl}}"}]},"inputParams":[{"field":"content","name":"question","nodeId":"start-node"},{"field":"ddl","name":"ddl","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"223993058876952576","type":"end","x":1652,"y":1408,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"text","name":"prompt","nodeId":"223992240450801664"}],"height":114,"width":332}}],"edges":[{"id":"172957153288454144","type":"base-edge","sourceNodeId":"172956395755208704","targetNodeId":"172957153284259840","sourceAnchorId":"172956395755208704_output","targetAnchorId":"172957153284259840_input","pointsList":[{"x":1332,"y":101},{"x":1432,"y":101},{"x":1377,"y":103},{"x":1477,"y":103}]},{"id":"173365501234540544","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"173365501230346240","sourceAnchorId":"start-node_output","targetAnchorId":"173365501230346240_input","pointsList":[{"x":428,"y":443},{"x":528,"y":443},{"x":422,"y":469},{"x":522,"y":469}]},{"id":"173366253650735104","type":"base-edge","sourceNodeId":"173365800833675264","targetNodeId":"173366253646540800","sourceAnchorId":"173365800833675264_output","targetAnchorId":"173366253646540800_input","pointsList":[{"x":1333,"y":309},{"x":1433,"y":309},{"x":1377,"y":310},{"x":1477,"y":310}]},{"id":"173372961415852032","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"172956395755208704","sourceAnchorId":"173365501230346240_source_if","targetAnchorId":"172956395755208704_input","pointsList":[{"x":854,"y":503},{"x":954,"y":503},{"x":900,"y":101},{"x":1000,"y":101}]},{"id":"173372967073968128","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"173365800833675264","sourceAnchorId":"173365501230346240_case_2","targetAnchorId":"173365800833675264_input","pointsList":[{"x":854,"y":529},{"x":954,"y":529},{"x":901,"y":309},{"x":1001,"y":309}]},{"id":"173372974988619776","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"173366439085109248","sourceAnchorId":"173365501230346240_source_else","targetAnchorId":"173366439085109248_input","pointsList":[{"x":854,"y":685},{"x":954,"y":685},{"x":900,"y":1636},{"x":1000,"y":1636}]},{"id":"175149164437209088","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"175149164433014784","sourceAnchorId":"173365501230346240_case_3","targetAnchorId":"175149164433014784_input","pointsList":[{"x":854,"y":555},{"x":954,"y":555},{"x":898,"y":539},{"x":998,"y":539}]},{"id":"175153997969915904","type":"base-edge","sourceNodeId":"175149164433014784","targetNodeId":"175153953988444160","sourceAnchorId":"175149164433014784_output","targetAnchorId":"175153953988444160_input","pointsList":[{"x":1330,"y":539},{"x":1430,"y":539},{"x":1377,"y":538},{"x":1477,"y":538}]},{"id":"175505963489439744","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"175505963485245440","sourceAnchorId":"173365501230346240_case_4","targetAnchorId":"175505963485245440_input","pointsList":[{"x":854,"y":581},{"x":954,"y":581},{"x":900,"y":743},{"x":1000,"y":743}]},{"id":"175506006648827904","type":"base-edge","sourceNodeId":"175505963485245440","targetNodeId":"175506006644633600","sourceAnchorId":"175505963485245440_output","targetAnchorId":"175506006644633600_input","pointsList":[{"x":1332,"y":743},{"x":1432,"y":743},{"x":1377,"y":743},{"x":1477,"y":743}]},{"id":"175807569598234624","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"175807569594040320","sourceAnchorId":"173365501230346240_case_5","targetAnchorId":"175807569594040320_input","pointsList":[{"x":854,"y":607},{"x":954,"y":607},{"x":900,"y":959},{"x":1000,"y":959}]},{"id":"175808663019732992","type":"base-edge","sourceNodeId":"175807569594040320","targetNodeId":"175808663015538688","sourceAnchorId":"175807569594040320_output","targetAnchorId":"175808663015538688_input","pointsList":[{"x":1332,"y":959},{"x":1432,"y":959},{"x":1377,"y":959},{"x":1477,"y":959}]},{"id":"221512800426758145","type":"base-edge","sourceNodeId":"221504502491222016","targetNodeId":"221512800426758144","sourceAnchorId":"221504502491222016_output","targetAnchorId":"221512800426758144_input","pointsList":[{"x":1332,"y":1178},{"x":1432,"y":1178},{"x":1377,"y":1175},{"x":1477,"y":1175}]},{"id":"221534054756093952","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"221504502491222016","sourceAnchorId":"173365501230346240_case_6","targetAnchorId":"221504502491222016_input","pointsList":[{"x":854,"y":633},{"x":954,"y":633},{"x":900,"y":1178},{"x":1000,"y":1178}]},{"id":"223992240454995968","type":"base-edge","sourceNodeId":"173365501230346240","targetNodeId":"223992240450801664","sourceAnchorId":"173365501230346240_case_7","targetAnchorId":"223992240450801664_input","pointsList":[{"x":854,"y":659},{"x":954,"y":659},{"x":900,"y":1382},{"x":1000,"y":1382}]},{"id":"223993058881146880","type":"base-edge","sourceNodeId":"223992240450801664","targetNodeId":"223993058876952576","sourceAnchorId":"223992240450801664_output","targetAnchorId":"223993058876952576_input","pointsList":[{"x":1332,"y":1382},{"x":1432,"y":1382},{"x":1386,"y":1382},{"x":1486,"y":1382}]}]}', 'enable', '{"outputs":[{"field":"text","name":"prompt","nodeId":"223992240450801664"},{"field":"outputText","type":"string"}],"inputs":[{"field":"content","name":"用户问题","required":true,"type":"string"},{"field":"history","name":"历史记录","required":false,"type":"string[]"},{"field":"ddl","name":"表结构","required":true,"type":"string"},{"field":"dbtype","name":"数据库类型","required":true,"type":"string"},{"field":"bizType","name":"业务类型","required":true,"type":"string"}]}');
