enter\\" }]\\n},\\n{ \\"type\\": \\"\\", \\"value\\": \\"普通文本内容示例\\" },\\n{\\n\\"type\\": \\"list\\",\\n\\"listType\\": \\"ul\\",\\n\\"listStyle\\": \\"disc\\",\\n\\"valueList\\": [\\n{ \\"value\\": \\"列表项1\\" },\\n{ \\"value\\": \\"列表项2\\" }\\n]\\n}\\n]\\n\\n\\n执行步骤：\\n1. 根据用户需求生成json数据\\n2. 检查生产的json数据是否正确。如果正常，输出给用户；否则重新生成。"},{"role":"user","content":"请根据以上字段和示例，生成一个完整的个人简历文档 JSON。\\n- 至少包含基础信息、个人优势、工作经历、项目经理、教育经历等模块。\\n- 若基础数据不足，可以适当生成参考数据。\\n- 用户信息如下：\\n基础资料：{{base}}\\n简介：{{profile}}"}]},"inputParams":[{"field":"profile","name":"base","nodeId":"start-node"},{"field":"content","name":"profile","nodeId":"start-node"}],"outputParams":[{"field":"text","name":"回复内容","type":"string"}],"height":180,"width":332}},{"id":"215735188368998400","type":"end","x":1577,"y":354,"properties":{"text":"结束","options":{"outputText":false,"outputContent":""},"inputParams":[],"outputParams":[{"field":"result","name":"resp","nodeId":"215740280715427840"}],"height":114,"width":332}},{"id":"215740280715427840","type":"enhanceJava","x":1156,"y":352,"properties":{"text":"Java 增强","options":{"enhance":{"type":"spring","path":"jeecgDemoAiWordGen"}},"inputParams":[{"field":"text","name":"resp","nodeId":"215734195065536512"}],"outputParams":[{"field":"result","name":"返回结果","type":"string"}],"height":180,"width":332}}],"edges":[{"id":"215734195073925120","type":"base-edge","sourceNodeId":"start-node","targetNodeId":"215734195065536512","sourceAnchorId":"start-node_output","targetAnchorId":"215734195065536512_input","pointsList":[{"x":466,"y":389},{"x":566,"y":389},{"x":473,"y":347},{"x":573,"y":347}]},{"id":"215740280719622144","type":"base-edge","sourceNodeId":"215734195065536512","targetNodeId":"215740280715427840","sourceAnchorId":"215734195065536512_output","targetAnchorId":"215740280715427840_input","pointsList":[{"x":905,"y":347},{"x":1005,"y":347},{"x":890,"y":293},{"x":990,"y":293}]},{"id":"215740398487289856","type":"base-edge","sourceNodeId":"215740280715427840","targetNodeId":"215735